'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const E = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const F = n => new Intl.NumberFormat('id-ID').format(Number(n)||0);
const RP = n => n===null||n===undefined||n===''?'—':'Rp '+F(n);
const DT = s => s?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Makassar'}).format(new Date(s)):'—';
const DTM = s => s?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Makassar'}).format(new Date(s)):'—';
const DAY = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const UID = () => typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
const conditionOptions=['BAGUS','LAYAK PAKAI','TIDAK LAYAK PAKAI','RUSAK','BELUM DIPERIKSA'];
const categoryOptions=['ASET','INVENTARIS'];
const statusOptions=['TERPAKAI','TIDAK TERPAKAI'];
const mm=['DILAPORKAN','DIJADWALKAN','DIPROSES','MENUNGGU_PART','SELESAI','DIBATALKAN'];
const menus=[['dashboard','Dashboard','dashboard'],['assets','Master Aset','box'],['statuses','Status Aset','activity'],['loans','Peminjaman','repeat'],['transfers','Transfer Aset','truck'],['ba','Buat BA & Approval','file'],['so','Stock Opname','clipboard'],['maintenance','Maintenance','tool'],['audit','Audit Log','clock'],['legacy','Riwayat Migrasi','file'],['users','Pengguna','users'],['branches','Lokasi / Cabang','map']];
const paths={
 dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 box:'<path d="m3 8 9-5 9 5v9l-9 5-9-5V8Z"/><path d="m3 8 9 5 9-5M12 13v9"/>',
 activity:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V9a3 3 0 0 1 3-3h15M7 22l-4-4 4-4m14-1v2a3 3 0 0 1-3 3H3"/>',
 truck:'<rect x="1" y="5" width="14" height="12" rx="1"/><path d="M15 9h4l3 3v5h-7M5 17a2 2 0 1 0 4 0M17 17a2 2 0 1 0 4 0"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
 clipboard:'<rect x="5" y="4" width="14" height="18" rx="2"/><rect x="9" y="2" width="6" height="5" rx="1"/><path d="m9 15 2 2 4-4"/>',
 tool:'<path d="M14.7 6.3A6 6 0 0 0 7 14l-5 5 3 3 5-5a6 6 0 0 0 7.7-7.7l-4.4 4.4-3-3Z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M17 5a3 3 0 0 1 0 6m2 9v-2a5 5 0 0 0-3-4.6"/>',
 map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3V6Zm6-3v15M15 6v15"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 17v4h16v-4"/>',
 arrow:'<path d="m9 18 6-6-6-6"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',chevron:'<path d="m6 9 6 6 6-6"/>',alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v1"/>',
 check:'<path d="m5 12 4 4L19 6"/>',trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/>',collapse:'<path d="m15 18-6-6 6-6"/>',expand:'<path d="m9 18 6-6-6-6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'
};
function ico(n){return `<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.box}</svg>`;}
const S={client:null,user:null,profile:null,data:{},catalog:[],view:'dashboard',filter:{q:'',branch:'ALL',category:'ALL',status:'ALL',condition:'ALL'},special:'',page:0,quick:'ALL',soId:null,loading:false,sidebarCollapsed:localStorage.getItem('ac_sidebar_collapsed')==='1'};
function branchName(id){return S.data.branches?.find(x=>x.id===id)?.name||'—';}
function personName(id){return S.data.profiles?.find(x=>x.id===id)?.display_name||String(id||'—').slice(0,8);}
function assetName(id){const a=S.data.assets?.find(x=>x.id===id)||S.catalog.find(x=>x.id===id);return a?.name||'—';}
function assetObj(id){return S.data.assets?.find(x=>x.id===id);}
function role(){return S.profile?.role||'';}
function globalUser(){return ['ADMIN','GA','FAT','AUDITOR'].includes(role());}
function manager(){return ['ADMIN','GA'].includes(role());}
function isMasterAdmin(){return role()==='ADMIN'&&S.profile?.active===true;}
function deleteBtn(entity,id,label='Hapus'){return isMasterAdmin()?`<button type="button" class="ghost-button danger-link" data-action="delete-record" data-entity="${E(entity)}" data-id="${E(id)}" title="Hapus permanen dari Supabase">${ico('trash')} ${E(label)}</button>`:'';}
function progressMeter(current,total,label='Progres'){const n=Number(current)||0,d=Math.max(0,Number(total)||0),pct=d?Math.min(100,Math.max(0,Math.round(n/d*100))):0;return `<div class="progress-item" role="progressbar" aria-label="${E(label)}" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span>${E(label)} <b>${F(n)}/${F(d)} · ${pct}%</b></span><div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div></div>`;}
function activeUser(){return ['ADMIN','GA','STORE'].includes(role());}
function canBA(){return ['ADMIN','GA','STORE'].includes(role());}
function options(arr,current,placeholder){return (placeholder?`<option value="">${E(placeholder)}</option>`:'')+arr.map(o=>{const v=typeof o==='object'?o.value:o,l=typeof o==='object'?o.label:o;return `<option value="${E(v)}" ${String(v)===String(current)?'selected':''}>${E(l)}</option>`;}).join('');}
function branchOpts(current,all=false){return options([...(all?[{value:'ALL',label:'Semua Lokasi'}]:[]),...(S.data.branches||[]).filter(x=>x.active).map(x=>({value:x.id,label:x.name}))],current);}
function fld(label,name,value='',type='text',extra=''){return `<label>${E(label)}<input class="field" name="${E(name)}" type="${E(type)}" value="${E(value)}" ${extra}></label>`;}
function sel(label,name,arr,value='',extra=''){return `<label>${E(label)}<select class="field" name="${E(name)}" ${extra}>${options(arr,value)}</select></label>`;}
function txt(label,name,value='',extra=''){return `<label class="wide">${E(label)}<textarea class="field" name="${E(name)}" ${extra}>${E(value)}</textarea></label>`;}
function labelStatus(v){return String(v||'—').replaceAll('_',' ');}
function tag(v){const s=String(v||'').toUpperCase();const cl=/DITOLAK|DIBATALKAN|RUSAK|TIDAK LAYAK|KRITIS|TERLAMBAT/.test(s)?'red':/TERPAKAI|DITERIMA|DISETUJUI|SELESAI|BAGUS|DIKEMBALIKAN/.test(s)&&!s.startsWith('TIDAK')?'green':/MENUNGGU|DILAPORKAN|DRAFT|DIAJUKAN|DIJADWALKAN|MENUNGGU PART/.test(s)?'orange':'blue';return `<span class="tag ${cl}">${E(labelStatus(v))}</span>`;}
function button(label,action,opts=''){return `<button type="button" class="button ${opts}" data-action="${E(action)}">${label}</button>`;}
function table(headers,rows){
 // Set label setiap sel agar pada tablet/HP tabel berubah menjadi kartu vertikal,
 // tanpa mengandalkan scroll horizontal.
 const labelled=rows.map(row=>{let col=0;return row.replace(/<td(?=[\s>])/g,match=>`<td data-label="${E(headers[col++]||'Detail')}"`);});
 return `<div class="tablewrap"><table class="table"><thead><tr>${headers.map(x=>`<th>${E(x)}</th>`).join('')}</tr></thead><tbody>${labelled.length?labelled.join(''):`<tr class="table-empty"><td colspan="${headers.length}"><div class="empty">${ico('search')}<div>Belum ada data sesuai pilihan</div></div></td></tr>`}</tbody></table></div>`;
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toast-root').append(el);setTimeout(()=>el.remove(),4700);}
function errorMessage(err){console.error(err);toast(err?.message||String(err),true);}
function loading(v){S.loading=v;let existing=$('.loadingline');if(v&&!existing){const el=document.createElement('div');el.className='loadingline';el.style.cssText='position:fixed;z-index:90;left:0;top:0;width:100%';document.body.append(el);}if(!v&&existing)existing.remove();}
async function run(fn,ok='Data berhasil disimpan'){if(S.loading)return false;loading(true);try{await fn();await loadData();render();toast(ok);return true;}catch(e){errorMessage(e);return false;}finally{loading(false);}}
function qerr(r){if(r.error)throw r.error;return r.data;}
async function readAll(table,max=8000){let out=[];for(let from=0;from<max;from+=800){const part=qerr(await S.client.from(table).select('*').range(from,from+799));out.push(...part);if(part.length<800)break;}return out;}
async function loadData(){
 const c=S.client;const [branches,assets,loans,ba,approvals,transfers,maintenance,photos,so,soItems,profiles,audit,catalog,legacy,codeHistory]=await Promise.all([
  readAll('ac_branches'),readAll('ac_assets'),readAll('ac_loans'),readAll('ac_ba'),readAll('ac_ba_approvals'),readAll('ac_transfers'),readAll('ac_maintenance'),readAll('ac_maintenance_photos'),readAll('ac_stock_opnames'),readAll('ac_so_items'),readAll('ac_profiles'),
  c.from('ac_audit').select('*').order('at',{ascending:false}).limit(250).then(qerr),
  canBA()?c.rpc('ac_transfer_catalog').then(qerr):Promise.resolve([]),
  globalUser()?c.from('ac_legacy_records').select('*').order('imported_at',{ascending:false}).limit(1500).then(r=>r.error?[]:r.data):Promise.resolve([]),
  readAll('ac_asset_code_history')
 ]);
 S.data={branches,assets,loans,ba,approvals,transfers,maintenance,photos,so,soItems,profiles,audit,legacy,codeHistory};S.catalog=catalog||[];
}
function iconNav(item){return ico(item[2]);}
function sidebar(){const visible=menus.filter(m=>!((m[0]==='users'||m[0]==='branches')&&role()!=='ADMIN')&&!(['audit','legacy'].includes(m[0])&&!globalUser()));return `<div id="shade" class="screen-overlay" data-action="close-nav"></div><aside id="sidebar" class="sidebar" aria-label="Menu navigasi"><div class="brand"><span class="brand-mark">38</span><div>TIGALAPAN<small>ASSET CONTROL</small></div></div><div class="nav-section">WORKSPACE</div>${visible.map(m=>`<button class="nav-link ${S.view===m[0]?'active':''}" data-nav="${E(m[0])}" title="${E(m[1])}" aria-label="${E(m[1])}">${iconNav(m)}<span>${E(m[1])}</span></button>`).join('')}<div class="sidebottom"><span class="dot"></span>Database Supabase Aktif<div>Role: ${E(role())}</div><div>${E(globalUser()?'Lintas cabang':branchName(S.profile.branch_id))}</div></div></aside>`;}
function shell(){const m=menus.find(x=>x[0]===S.view);return `<div class="layout ${S.sidebarCollapsed?'sidebar-collapsed':''}">${sidebar()}<main class="workspace"><header class="topbar"><div class="actions"><button class="button outline small mobile-menu" data-action="open-nav" aria-label="Buka menu">${ico('menu')}</button><button class="button outline small desktop-collapse" data-action="toggle-sidebar" title="Lipat atau buka menu" aria-label="Lipat atau buka menu">${ico(S.sidebarCollapsed?'expand':'collapse')}</button><div><div class="kicker">TIGALAPAN INDONESIA / ASSET MANAGEMENT</div><h2>${E(m?.[1]||'Dashboard')}</h2></div></div><div class="top-right"><div class="profile-avatar">${E((S.profile.display_name||'?')[0].toUpperCase())}</div><div><div class="profile-name">${E(S.profile.display_name)}</div><div class="profile-meta">${E(role())} · ${E(globalUser()?'All locations':branchName(S.profile.branch_id))}</div></div><button class="button outline small" data-action="logout">Keluar</button></div></header><div class="content" id="content"></div></main></div>`;}
function head(title,desc,actions=''){return `<div class="heading"><div><h1>${E(title)}</h1><p>${E(desc)}</p></div><div class="actions">${actions}</div></div>`;}
function stat(title,value,note,dest,filter='',color='',symbol='box'){return `<button class="stat ${color}" data-action="dash" data-dest="${E(dest)}" data-filter="${E(filter)}"><div class="stat-symbol">${ico(symbol)}</div><div class="stat-title">${E(title)}</div><div class="stat-value mono">${E(value)}</div><div class="stat-note">${E(note)} →</div></button>`;}
function barChart(title,values,type='branch',color=''){const entries=Object.entries(values).sort((a,b)=>b[1]-a[1]).slice(0,9);const max=Math.max(1,...entries.map(x=>x[1]));const total=Object.values(values).reduce((n,v)=>n+Number(v||0),0);return `<section class="panel"><h3>${E(title)}</h3>${entries.map(([label,value])=>`<div class="barrow" title="Klik untuk lihat data" data-action="chart-filter" data-filtertype="${E(type)}" data-value="${E(label)}" style="cursor:pointer"><span class="barname">${E(label)}</span><div class="track"><div class="bar ${color}" style="width:${(value/max*100).toFixed(1)}%"></div></div><b class="mono">${F(value)} <small>${total?Math.round(value/total*100):0}%</small></b></div>`).join('')||'<p class="muted">Belum ada data.</p>'}</section>`;}
function getFilteredAssets(){let rows=S.data.assets||[];const f=S.filter;
 if(f.branch!=='ALL')rows=rows.filter(a=>a.branch_id===f.branch);
 if(f.category!=='ALL')rows=rows.filter(a=>a.category===f.category);
 if(f.status!=='ALL')rows=rows.filter(a=>a.status===f.status);
 if(f.condition!=='ALL')rows=rows.filter(a=>a.condition===f.condition);
 if(f.q){const q=f.q.toLowerCase();rows=rows.filter(a=>[a.name,a.asset_code,a.brand,a.registration_no,a.position,branchName(a.branch_id),a.category,a.owner_name].some(s=>String(s||'').toLowerCase().includes(q)) || (S.data.codeHistory||[]).some(h=>h.asset_id===a.id && [h.previous_code,h.new_code].some(v=>String(v||'').toLowerCase().includes(q))));}
 if(S.special==='RUSAK')rows=rows.filter(a=>['RUSAK','TIDAK LAYAK PAKAI'].includes(a.condition));
 if(S.special==='NO_FAT')rows=rows.filter(a=>a.category==='ASET'&&!a.registration_no);
 return rows;
}
function resetFilters(){S.filter={q:'',branch:role()==='STORE'?S.profile.branch_id:'ALL',category:'ALL',status:'ALL',condition:'ALL'};S.special='';S.page=0;S.quick='ALL';}
function filters(){return `<div class="filters"><input id="f-q" class="field search" placeholder="Cari ID, nama, merek, nomor FAT, posisi..." value="${E(S.filter.q)}"><select class="field" id="f-branch" ${role()==='STORE'?'disabled':''}>${branchOpts(S.filter.branch,true)}</select><select class="field" id="f-cat">${options(['ALL',...categoryOptions],S.filter.category)}</select><select class="field" id="f-status">${options(['ALL',...statusOptions],S.filter.status)}</select><select class="field" id="f-cond">${options(['ALL',...conditionOptions],S.filter.condition)}</select>${button('Reset','reset','outline small')}</div>`;}
function paginate(rows,size=40){const from=S.page*size;return {items:rows.slice(from,from+size),control:`<div class="paginator"><span>Menampilkan ${rows.length?F(from+1):0}–${F(Math.min(from+size,rows.length))} dari ${F(rows.length)} baris</span><div class="actions"><button class="button outline small" data-action="prev" ${S.page<=0?'disabled':''}>‹ Sebelumnya</button><button class="button outline small" data-action="next" ${(S.page+1)*size>=rows.length?'disabled':''}>Berikutnya ›</button></div></div>`};}
function tally(rows,key){const out={};for(const r of rows){const k=key(r)||'Belum diisi';out[k]=(out[k]||0)+Number(r.qty||0);}return out;}
function scoped(row,type='branch_id'){const b=S.filter.branch;return b==='ALL'||row[type]===b;}
function scopedBA(b){return S.filter.branch==='ALL'||b.from_branch_id===S.filter.branch||b.to_branch_id===S.filter.branch||assetObj(b.asset_id)?.branch_id===S.filter.branch||S.data.profiles.find(p=>p.id===b.recipient_id)?.branch_id===S.filter.branch;}
function renderDashboard(){const a=getFilteredAssets(),sum=a.reduce((n,x)=>n+x.qty,0),isBad=a.filter(x=>['RUSAK','TIDAK LAYAK PAKAI'].includes(x.condition)),loans=S.data.loans.filter(x=>scoped(x)&&x.status==='DIPINJAM'&&x.due_date<DAY()),pendingTrans=S.data.transfers.filter(x=>(S.filter.branch==='ALL'||x.from_branch_id===S.filter.branch||x.to_branch_id===S.filter.branch)&&!['DITERIMA','DITOLAK','DIBATALKAN'].includes(x.status)),openMaint=S.data.maintenance.filter(x=>scoped(x)&&!['SELESAI','DIBATALKAN'].includes(x.status)),pendingBA=S.data.ba.filter(x=>scopedBA(x)&&x.status==='MENUNGGU');
 const cards=[stat('Total Kelompok Aset',F(a.length),'Baris master aset','assets','','','box'),stat('Total Unit Terdata',F(sum),'Jumlah unit tercatat','assets','','blue','dashboard'),stat('Aset Terpakai',F(a.filter(x=>x.status==='TERPAKAI').reduce((n,x)=>n+x.qty,0)),'Unit status terpakai','assets','TERPAKAI','green','check'),stat('Aset Tidak Terpakai',F(a.filter(x=>x.status==='TIDAK TERPAKAI').reduce((n,x)=>n+x.qty,0)),'Unit tidak terpakai','assets','TIDAK TERPAKAI','red','box'),stat('Unit Rusak / Tidak Layak',F(isBad.reduce((n,x)=>n+x.qty,0)),'Perlu tindak lanjut','assets','RUSAK','red','alert'),stat('Aset Belum Nomor FAT',F(a.filter(x=>x.category==='ASET'&&!x.registration_no).length),'Kategori aset saja','assets','NO_FAT','','file'),stat('Peminjaman Terlambat',F(loans.length),'Lewat jatuh tempo','loans','OVERDUE','red','clock'),stat('Transfer Belum Selesai',F(pendingTrans.length),'Pengajuan sampai penerimaan','transfers','PENDING','blue','truck'),stat('BA Menunggu Persetujuan',F(pendingBA.length),'Approval berjenjang','ba','MENUNGGU','','file'),stat('Maintenance Terbuka',F(openMaint.length),'Tiket dalam penanganan','maintenance','OPEN','blue','tool'),stat('SO Menunggu Approval',F(S.data.so.filter(x=>scoped(x)&&x.status==='DIAJUKAN').length),'Belum disahkan GA','so','DIAJUKAN','green','clipboard')];
 return head('Executive Dashboard','Ringkasan aset perusahaan dan tindak lanjut operasional. Klik setiap kartu untuk membuka data terkait.',button(`${ico('download')} Export CSV`,'export-assets','outline'))+filters()+`<div class="dashboard-cards">${cards.join('')}</div><div class="panel progress-summary"><h3>Progres Pemakaian & Penyelesaian</h3><div class="progress-summary-grid">${progressMeter(a.filter(x=>x.status==='TERPAKAI').reduce((n,x)=>n+x.qty,0),sum,'Unit Terpakai')}${progressMeter(S.data.maintenance.filter(x=>scoped(x)&&x.status==='SELESAI').length,S.data.maintenance.filter(x=>scoped(x)).length,'Maintenance Selesai')}${progressMeter(S.data.ba.filter(x=>scopedBA(x)&&x.status==='DISETUJUI').length,S.data.ba.filter(scopedBA).length,'BA Disetujui')}</div></div><div class="panels">${barChart('Distribusi Unit per Lokasi',tally(a,x=>branchName(x.branch_id)),'branch')}${barChart('Kondisi Aset (unit)',tally(a,x=>x.condition),'condition','green')}${barChart('Kategori Aset / Inventaris (unit)',tally(a,x=>x.category),'category','blue')}${barChart('Status Pemakaian (unit)',tally(a,x=>x.status),'status','green')}</div><div class="smalltext">Jumlah unit mengikuti QTY. Total kelompok aset dihitung per ID master. Kartu lintas proses mengikuti izin akses user.</div>`;
}
function assetAction(x){return `<button class="ghost-button" data-action="asset-detail" data-id="${E(x.id)}">Detail</button>${manager()?` <button class="ghost-button" data-action="asset-edit" data-id="${E(x.id)}">Edit</button>`:''} ${deleteBtn('ASSET',x.id)}`;}
function assetTable(rows){const p=paginate(rows);return table(['Nama & ID','Merek','Kategori','Lokasi / Posisi','Qty','Kondisi','Status','Maintenance','Aksi'],p.items.map(x=>`<tr><td><strong>${E(x.name)}</strong><small>${E(x.asset_code)} · FAT ${E(x.registration_no||'Belum diisi')}</small></td><td>${E(x.brand||'—')}</td><td>${tag(x.category)}</td><td>${E(branchName(x.branch_id))}<small>${E(x.position||'—')}</small></td><td><strong class="mono">${F(x.qty)}</strong></td><td>${tag(x.condition)}</td><td>${tag(x.status)}</td><td><button class="ghost-button" data-action="asset-history" data-id="${E(x.id)}">${F(S.data.maintenance.filter(m=>m.asset_id===x.id).length)} riwayat</button></td><td>${assetAction(x)}</td></tr>`))+p.control;}
function renderAssets(){const rows=getFilteredAssets();return head('Master Aset & Inventaris','Master terpusat dengan kategori ASET / INVENTARIS dan riwayat maintenance otomatis.',`${manager()?button(`${ico('plus')} Tambah Aset`,'asset-new'):''}${button(`${ico('download')} Export CSV`,'export-assets','outline')}${manager()?button('Import CSV','asset-import','outline'):''}`)+filters()+`<div class="hint">Kategori pencatatan hanya <b>ASET</b> dan <b>INVENTARIS</b>. Nomor registrasi FAT diisi untuk kategori ASET menurut kebijakan perusahaan. Riwayat maintenance mengikuti ID aset dan lokasi.</div>`+assetTable(rows);}
function renderStatuses(){const a=getFilteredAssets();return head('Status Aset','Hanya dua status: TERPAKAI dan TIDAK TERPAKAI; kondisi fisik tetap dicatat terpisah.')+filters()+`<div class="dashboard-cards">${stat('Unit Terpakai',F(a.filter(x=>x.status==='TERPAKAI').reduce((n,x)=>n+x.qty,0)),'Lihat aset terpakai','assets','TERPAKAI','green')}${stat('Unit Tidak Terpakai',F(a.filter(x=>x.status==='TIDAK TERPAKAI').reduce((n,x)=>n+x.qty,0)),'Lihat aset tidak terpakai','assets','TIDAK TERPAKAI','red')}${stat('Total Baris Aset',F(a.length),'Lihat master','assets','','blue')}${stat('Kondisi Tidak Layak',F(a.filter(x=>x.condition==='TIDAK LAYAK PAKAI').reduce((n,x)=>n+x.qty,0)),'Lihat kondisi','assets','RUSAK','red')}</div>${assetTable(a)}`;}
function renderLoans(){let rows=S.data.loans.filter(x=>scoped(x)).sort((a,b)=>b.created_at.localeCompare(a.created_at));if(S.quick==='OVERDUE')rows=rows.filter(x=>x.status==='DIPINJAM'&&x.due_date<DAY());return head('Peminjaman Aset','Pencatatan peminjam, tenggat pengembalian, dan kuantitas yang masih terpakai.',activeUser()?button(`${ico('plus')} Catat Peminjaman`,'loan-new'):'')+pills(['ALL','OVERDUE'],['Semua','Terlambat'])+table(['Nama Aset','Peminjam','Lokasi','Qty','Tanggal Pinjam','Jatuh Tempo','Status','Aksi'],rows.map(x=>`<tr><td><strong>${E(assetName(x.asset_id))}</strong></td><td>${E(x.borrower)}</td><td>${E(branchName(x.branch_id))}</td><td>${F(x.qty)}</td><td>${DT(x.borrow_date)}</td><td>${DT(x.due_date)}${x.status==='DIPINJAM'&&x.due_date<DAY()?`<small>${tag('TERLAMBAT')}</small>`:''}</td><td>${tag(x.status)}</td><td>${x.status==='DIPINJAM'&&activeUser()?`<button class="ghost-button" data-action="loan-return" data-id="${E(x.id)}">Kembalikan</button>`:'—'} ${deleteBtn('LOAN',x.id)}</td></tr>`));}
function renderTransfers(){let rows=S.data.transfers.filter(x=>S.filter.branch==='ALL'||x.from_branch_id===S.filter.branch||x.to_branch_id===S.filter.branch).sort((a,b)=>b.created_at.localeCompare(a.created_at));if(S.quick==='PENDING')rows=rows.filter(x=>!['DITERIMA','DITOLAK','DIBATALKAN'].includes(x.status));return head('Transfer Aset','Permintaan user → BA approval toko pengirim → GA → FAT → kirim → terima.',canBA()?button(`${ico('plus')} Ajukan Transfer (BA)`,'ba-new-transfer'):'')+pills(['ALL','PENDING'],['Semua transfer','Belum selesai'])+table(['ID Transfer / Aset','Dari','Ke','Qty','Status','BA','Aksi'],rows.map(x=>`<tr><td><strong>${E(assetName(x.asset_id))}</strong><small>${E(x.id.slice(0,8))}</small></td><td>${E(branchName(x.from_branch_id))}</td><td>${E(branchName(x.to_branch_id))}</td><td>${F(x.qty)}</td><td>${tag(x.status)}</td><td><button class="ghost-button" data-action="ba-detail" data-id="${E(x.ba_id)}">${E(S.data.ba.find(b=>b.id===x.ba_id)?.ba_number||'View BA')}</button></td><td><div class="controls">${transferButtons(x)} ${deleteBtn('TRANSFER',x.id)}</div></td></tr>`));}
function transferButtons(x){const from=manager()||(role()==='STORE'&&S.profile.branch_id===x.from_branch_id),to=manager()||(role()==='STORE'&&S.profile.branch_id===x.to_branch_id);return `${x.status==='MENUNGGU_BA'&&(x.requested_by===S.user.id||manager())?`<button class="ghost-button" data-action="tf-cancel" data-id="${E(x.id)}">Batalkan</button>`:''}${x.status==='DISETUJUI'&&from?`<button class="ghost-button" data-action="tf-ship" data-id="${E(x.id)}">Kirim</button>`:''}${x.status==='DALAM_PENGIRIMAN'&&to?`<button class="ghost-button" data-action="tf-receive" data-id="${E(x.id)}">Terima</button>`:''}`||'—';}
function pills(ids,labels){return `<div class="pill-row">${ids.map((x,i)=>`<button class="pill ${x===S.quick?'selected':''}" data-action="quick" data-value="${E(x)}">${E(labels[i])}</button>`).join('')}</div>`;}
function currentStep(b){return S.data.approvals.filter(x=>x.ba_id===b.id&&x.decision==='MENUNGGU').sort((a,c)=>a.step_no-c.step_no)[0];}
function mayApprove(step){return !!step&&((step.role_required==='USER'&&step.user_id===S.user.id)||(step.role_required==='STORE'&&role()==='STORE'&&step.branch_id===S.profile.branch_id)||(step.role_required===role())||role()==='ADMIN');}
function renderBA(){let rows=S.data.ba.filter(scopedBA).sort((a,b)=>b.created_at.localeCompare(a.created_at));if(S.quick!=='ALL')rows=rows.filter(x=>x.status===S.quick);return head('Berita Acara & Approval','BA HTML ringan; persetujuan terekam secara berjenjang dan dapat dicetak.',canBA()?button(`${ico('plus')} Buat BA`,'ba-new'):'')+pills(['ALL','MENUNGGU','DISETUJUI','DITOLAK'],['Semua','Menunggu','Disetujui','Ditolak'])+table(['No. BA / Judul','Jenis','Tanggal','Pembuat','Tahap Berikutnya','Status','Aksi'],rows.map(b=>{const step=currentStep(b);return `<tr><td><strong>${E(b.ba_number)}</strong><small>${E(b.title)}</small></td><td>${tag(b.ba_type)}</td><td>${DT(b.created_at)}</td><td>${E(personName(b.created_by))}</td><td>${step?`${E(step.step_no)}. ${E(step.label)}`:'—'}</td><td>${tag(b.status)}</td><td><div class="controls"><button class="ghost-button" data-action="ba-detail" data-id="${E(b.id)}">Lihat BA</button>${b.status==='MENUNGGU'&&mayApprove(step)?`<button class="ghost-button" data-action="ba-approve" data-id="${E(b.id)}">Approve</button><button class="ghost-button" data-action="ba-reject" data-id="${E(b.id)}">Tolak</button>`:''}${deleteBtn('BA',b.id)}</div><div class="mt10">${progressMeter(S.data.approvals.filter(a=>a.ba_id===b.id&&a.decision==='DISETUJUI').length,S.data.approvals.filter(a=>a.ba_id===b.id).length,'Approval')}</div></td></tr>`;}));}
function renderSO(){if(S.soId)return renderSODetail();let rows=S.data.so.filter(x=>scoped(x)).sort((a,b)=>b.created_at.localeCompare(a.created_at));if(S.quick==='DIAJUKAN')rows=rows.filter(x=>x.status==='DIAJUKAN');return head('Stock Opname Aset','Hitung aset fisik per cabang, ajukan, lalu rekonsiliasi dengan persetujuan GA.',activeUser()?button(`${ico('plus')} Mulai SO`,'so-new'):'')+pills(['ALL','DIAJUKAN'],['Semua sesi','Menunggu GA'])+table(['Sesi','Lokasi','Dibuat','Tanggal','Status','Aksi'],rows.map(x=>`<tr><td><strong>${E(x.id.slice(0,8))}</strong></td><td>${E(branchName(x.branch_id))}</td><td>${E(personName(x.created_by))}</td><td>${DT(x.created_at)}</td><td>${tag(x.status)}</td><td><button class="ghost-button" data-action="so-open" data-id="${E(x.id)}">Buka / Hitung</button> ${deleteBtn('SO',x.id)}</td></tr>`));}
function renderSODetail(){const so=S.data.so.find(x=>x.id===S.soId);if(!so){S.soId=null;return renderSO();}const items=S.data.soItems.filter(x=>x.so_id===so.id),draft=so.status==='DRAFT'&&activeUser();return `<div class="subnav"><button class="ghost-button" data-action="so-back">← Semua Sesi Stock Opname</button></div>`+head('SO — '+so.id.slice(0,8),`${branchName(so.branch_id)} · ${items.length} aset · ${labelStatus(so.status)}`,`${draft?button('Simpan Hitungan','so-save')+button('Ajukan ke GA','so-submit','dark'):''}${so.status==='DIAJUKAN'&&manager()?button('Approve & Rekonsiliasi','so-approve'):''}`)+`<div class="panel so-progress-panel">${progressMeter(items.filter(x=>x.qty_counted!==null).length,items.length,'Item SO Dihitung')}</div><div class="hint">Qty aktual 0 = tidak ditemukan. Kolom kosong = belum dihitung. Perubahan master akan ditolak jika qty berubah setelah sesi SO dibuat.</div>`+table(['Aset','Qty Sistem','Qty Aktual','Selisih','Kondisi Fisik','Catatan'],items.map(x=>{const a=assetObj(x.asset_id);return `<tr data-so-item="${E(x.id)}"><td><strong>${E(a?.name||'—')}</strong><small>${E(a?.asset_code||'')}</small></td><td>${F(x.qty_system)}</td><td>${draft?`<input class="field" style="width:90px" name="qty" type="number" min="0" step="1" value="${E(x.qty_counted??'')}">`:(x.qty_counted??'—')}</td><td>${x.qty_counted!==null?F(x.qty_counted-x.qty_system):'—'}</td><td>${draft?`<select class="field" name="condition">${options(conditionOptions,x.condition)}</select>`:tag(x.condition)}</td><td>${draft?`<input class="field" name="notes" value="${E(x.notes)}">`:E(x.notes||'—')}</td></tr>`;}));}
function renderMaintenance(){let rows=S.data.maintenance.filter(x=>scoped(x)).sort((a,b)=>b.created_at.localeCompare(a.created_at));if(S.quick==='OPEN')rows=rows.filter(x=>!['SELESAI','DIBATALKAN'].includes(x.status));return head('Maintenance & Service','Tiket kerusakan, preventive, inspeksi, vendor, biaya, SLA, dan bukti foto sebelum–sesudah.',activeUser()?button(`${ico('plus')} Buat Laporan`,'maintenance-new')+(isMasterAdmin()?button('Bersihkan Storage','cleanup-storage','outline'):''):'')+pills(['ALL','OPEN'],['Semua tiket','Belum selesai'])+table(['Tiket & Aset','Lokasi','Tipe','Prioritas','Keluhan','Target','Biaya Aktual','Status','Aksi'],rows.map(x=>`<tr><td><strong>${E(assetName(x.asset_id))}</strong><small>${E(x.ticket_code)} · ${DT(x.created_at)}</small></td><td>${E(branchName(x.branch_id))}</td><td>${E(x.maintenance_type)}</td><td>${tag(x.priority)}</td><td class="maxcell" title="${E(x.issue)}">${E(x.issue)}</td><td>${DT(x.due_date)}</td><td>${RP(x.actual_cost)}</td><td>${tag(x.status)}</td><td><button class="ghost-button" data-action="maintenance-detail" data-id="${E(x.id)}">Detail / Foto</button> ${deleteBtn('MAINTENANCE',x.id)}</td></tr>`));}
function renderLegacy(){
 const all=S.data.legacy||[]; const counts={};
 all.forEach(x=>{counts[x.entity]=(counts[x.entity]||0)+1;});
 const rows=all.filter(x=>!S.legacyType||S.legacyType==='ALL'||x.entity===S.legacyType);
 const open=all.filter(x=>x.entity==='TRANSFERS'&&!['DITERIMA','DITOLAK','DIBATALKAN'].includes(String(x.data?.status||'').toUpperCase())).length;
 const actions=`<select class="field" id="legacy-type" style="max-width:190px"><option value="ALL">Semua Tabel</option>${Object.keys(counts).sort().map(x=>`<option value="${E(x)}" ${S.legacyType===x?'selected':''}>${E(x)}</option>`).join('')}</select>`;
 return head('Arsip Migrasi Aplikasi Lama','Snapshot historis dari Google Sheets / Apps Script (read-only).',actions)
 +`<div class="hint">Data master aset, peminjaman, dan maintenance yang valid masuk menu operasional. TRANSFERS, CONDITIONS, SO, SO_ITEMS, dan AUDIT lama tersimpan sebagai arsip, tanpa menciptakan approval baru. Tampilan dibatasi 1.500 catatan terbaru.</div>`
 + (open?`<div class="hint" style="border-left:4px solid #e87921">Perhatian: ${F(open)} transfer lama berstatus belum selesai. Selesaikan secara manual / ajukan ulang melalui BA baru sebelum go-live.</div>`:'')
 +table(['Entitas','ID Aset Baru / Referensi','Lokasi','Status Lama','Waktu Import','Detail'],rows.map(x=>`<tr><td>${tag(x.entity)}</td><td>${E(x.data?.idAsetBaru||x.legacy_id)}</td><td>${E(branchName(x.branch_id))}</td><td>${E(x.data?.status||'—')}</td><td>${DTM(x.imported_at)}</td><td><button class="ghost-button" data-action="legacy-detail" data-id="${E(x.id)}">Lihat asli</button> ${deleteBtn('LEGACY',x.id)}</td></tr>`));
}
function legacyDetail(id){const r=(S.data.legacy||[]).find(x=>String(x.id)===String(id));if(!r)return;
 modal('Arsip Lama — '+r.entity+' / '+r.legacy_id,`<p class="smalltext">Data sumber asli, untuk audit. Metadata password/hash lama tidak disalin.</p><pre style="white-space:pre-wrap;overflow:auto;max-height:55vh;background:#f5f7fb;border-radius:10px;padding:14px;font-size:12px">${E(JSON.stringify(r.data,null,2))}</pre>`,null,'',true);
}
function renderAudit(){const rows=S.data.audit;return head('Audit Log','Jejak aktivitas database yang dapat diaudit; menampilkan 250 perubahan terakhir.')+table(['Waktu','Akun','Aksi','Entitas','ID','Perubahan'],rows.map(x=>`<tr><td>${DTM(x.at)}</td><td>${E(personName(x.actor))}</td><td>${tag(x.action)}</td><td>${E(x.entity)}</td><td>${E(x.entity_id.slice(0,8))}</td><td><button class="ghost-button" data-action="audit-detail" data-id="${E(x.id)}">Lihat perubahan</button> ${deleteBtn('AUDIT',x.id)}</td></tr>`));}
function auditDetail(id){const a=S.data.audit.find(x=>String(x.id)===String(id));if(!a)return;
 const before=a.details?.before||{},after=a.details?.after||{};const changes=[...new Set([...Object.keys(before),...Object.keys(after)])].filter(k=>JSON.stringify(before[k])!==JSON.stringify(after[k])&& !['updated_at'].includes(k));
 modal(`Audit Log — ${a.entity} / ${a.action}`,`<div class="detail-grid">${hx('Waktu',DTM(a.at))}${hx('Aktor',personName(a.actor))}${hx('Entitas',a.entity)}${hx('ID Entitas',a.entity_id)}</div><h3 class="section-title">Perubahan Data (${changes.length} kolom)</h3>${table(['Kolom','Sebelum','Sesudah'],changes.map(k=>`<tr><td>${E(k)}</td><td class="maxcell">${E(typeof before[k]==='object'?JSON.stringify(before[k]):before[k]??'—')}</td><td class="maxcell">${E(typeof after[k]==='object'?JSON.stringify(after[k]):after[k]??'—')}</td></tr>`))}`,null,'',true);
}
function renderUsers(){return head('Pengguna & Hak Akses','Akun dibuat di Supabase Authentication; ADMIN menetapkan role, lokasi, dan aktivasi.')+`<div class="hint">Buat user baru di Supabase Dashboard → Authentication → Users → Add user. Setelah akun dibuat, profilnya muncul di bawah dalam keadaan nonaktif. Anda dapat mengaktifkan dan menentukan role/lokasi melalui aplikasi.</div>`+table(['Nama','Email/Login ID','Role','Cabang','Status','Aksi'],S.data.profiles.map(x=>`<tr><td><strong>${E(x.display_name)}</strong></td><td>${E(x.id.slice(0,8))}</td><td>${tag(x.role)}</td><td>${E(branchName(x.branch_id))}</td><td>${tag(x.active?'AKTIF':'BELUM AKTIF')}</td><td><button class="ghost-button" data-action="user-edit" data-id="${E(x.id)}">Kelola</button> ${x.id!==S.user.id?deleteBtn('USER',x.id):''}</td></tr>`));}
function renderBranches(){return head('Master Lokasi / Cabang','Daftar lokasi untuk registrasi aset, BA, transfer, dan maintenance.',button(`${ico('plus')} Tambah Cabang`,'branch-new'))+table(['Nama Cabang','Status','Aksi'],S.data.branches.map(x=>`<tr><td><strong>${E(x.name)}</strong></td><td>${tag(x.active?'AKTIF':'NONAKTIF')}</td><td><button class="ghost-button" data-action="branch-edit" data-id="${E(x.id)}">Edit</button> ${deleteBtn('BRANCH',x.id)}</td></tr>`));}
function render(){if(!S.profile)return;const view={dashboard:renderDashboard,assets:renderAssets,statuses:renderStatuses,loans:renderLoans,transfers:renderTransfers,ba:renderBA,so:renderSO,maintenance:renderMaintenance,audit:renderAudit,legacy:renderLegacy,users:renderUsers,branches:renderBranches};$('#app').innerHTML=shell();$('#content').innerHTML=(view[S.view]||renderDashboard)();}
function nav(v){S.view=v;S.page=0;S.quick='ALL';S.soId=null;S.special='';render();}

function closeModal(){$('#modal-root').innerHTML='';}
function modal(title,content,onSave=null,submitLabel='Simpan',wide=false){
 $('#modal-root').innerHTML=`<div class="overlay"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><header class="modal-head"><h3>${E(title)}</h3><button class="close" type="button" data-action="modal-close" aria-label="Tutup">×</button></header><form id="dialog-form"><div class="modal-body">${content}</div><footer class="modal-foot"><button class="button outline" type="button" data-action="modal-close">Tutup</button>${onSave?`<button class="button" type="submit">${E(submitLabel)}</button>`:''}</footer></form></div></div>`;
 if(onSave)$('#dialog-form').addEventListener('submit',async ev=>{ev.preventDefault();if(S.loading)return;const fd=new FormData(ev.target);loading(true);const b=$('#dialog-form [type="submit"]');if(b)b.disabled=true;try{await onSave(fd,ev.target);closeModal();await loadData();render();toast('Data berhasil disimpan.');}catch(e){if(e.partialSave){closeModal();await loadData();render();toast(e.message,true);}else errorMessage(e);}finally{loading(false);if(b)b.disabled=false;}});
}
function hx(title,value){return `<div class="detail"><label>${E(title)}</label><b>${E(value??'—')}</b></div>`;}
function codeHistoryRows(a){
 const rows=(S.data.codeHistory||[]).filter(h=>h.asset_id===a.id).sort((x,y)=>y.changed_at.localeCompare(x.changed_at));
 return `<h4 class="section-title">Riwayat Perubahan ID Aset · ${rows.length}</h4>${rows.length?table(['Tanggal','Kategori Lama → Baru','Nomor Sebelumnya','Nomor Baru'],rows.map(h=>`<tr><td>${E(DTM(h.changed_at))}</td><td>${E(h.previous_category)} → ${E(h.new_category)}</td><td class="mono">${E(h.previous_code)}</td><td class="mono">${E(h.new_code)}</td></tr>`)):'<p class="smalltext">Nomor belum pernah berubah.</p>'}<p class="smalltext mt10">Identitas internal UUID tetap sama. Nomor lama dapat dicari di Master Aset.</p>`;
}
function baAssetCodeAtCreation(b){
 const asset=assetObj(b.asset_id)||S.catalog.find(a=>a.id===b.asset_id);
 if(!asset)return '';
 const createdMs=Date.parse(b.created_at);const later=(S.data.codeHistory||[]).filter(h=>h.asset_id===b.asset_id && Date.parse(h.changed_at)>=createdMs).sort((x,y)=>Date.parse(x.changed_at)-Date.parse(y.changed_at) || x.id-y.id);
 return later.length?later[0].previous_code:asset.asset_code;
}
function historyRows(a){const rows=S.data.maintenance.filter(m=>m.asset_id===a.id).sort((x,y)=>y.created_at.localeCompare(x.created_at));return `<h4 class="section-title">History Maintenance Otomatis · ${rows.length} tiket</h4>${table(['Tanggal','Lokasi','Tiket','Kebutuhan','Penanganan','Biaya','Status'],rows.map(m=>`<tr><td>${DT(m.created_at)}</td><td>${E(branchName(m.branch_id))}</td><td><button class="ghost-button" data-action="maintenance-detail" data-id="${E(m.id)}">${E(m.ticket_code)}</button></td><td>${E(m.maintenance_type)}<small>${E(m.issue.slice(0,70))}</small></td><td>${E(m.action||'—')}</td><td>${RP(m.actual_cost)}</td><td>${tag(m.status)}</td></tr>`))}<p class="smalltext mt10">Riwayat mengikuti ID aset, dengan lokasi saat masing-masing laporan dibuat. Data migrasi lokasi lama tetap terlihat.</p>`;}
function assetDetail(id,onlyHistory=false){const a=assetObj(id);if(!a)return toast('Aset tidak ditemukan.',true);modal(onlyHistory?`History Maintenance — ${a.name}`:`Detail Aset — ${a.asset_code}`,`${onlyHistory?'':`<div class="detail-grid">${hx('Nama',a.name)}${hx('Kategori',a.category)}${hx('Status Pemakaian',a.status)}${hx('Kondisi Fisik',a.condition)}${hx('Cabang',branchName(a.branch_id))}${hx('Posisi',a.position)}${hx('Jumlah',F(a.qty))}${hx('Merek / Tipe',a.brand)}${hx('No. FAT',a.registration_no)}${hx('Nomor Seri',a.serial_no)}${hx('Harga Pembelian',RP(a.purchase_price))}${hx('Tanggal Pembelian',DT(a.purchase_date))}${hx('Penanggung Jawab',a.owner_name)}${hx('Sumber',a.source)}</div>${a.notes?`<div class="hint mt16">${E(a.notes)}</div>`:''}${a.photo_url?.startsWith('https://')?`<p class="mt16"><a href="${E(a.photo_url)}" target="_blank" rel="noopener noreferrer">Lihat foto aset ↗</a></p>`:''}<div class="divider"></div>`}${codeHistoryRows(a)}${historyRows(a)}`,null,'',true);}
function assetForm(id){const a=assetObj(id)||{},old=!!id;modal(old?'Edit Master Aset':'Registrasi Aset Baru',`<div class="form-grid">${fld('Nama Aset *','name',a.name,'text','required maxlength="200"')}${fld('Merek / Tipe','brand',a.brand)}${sel('Kategori Aset *','category',categoryOptions,a.category||'ASET')}<div class="wide hint">${old?`ID sekarang: <b>${E(a.asset_code)}</b>. `:'ID diterbitkan otomatis saat disimpan. '}ASET = <b>AST-YYYY-000001</b>; INVENTARIS = <b>INV-YYYY-000001</b>. Mengubah kategori akan menerbitkan nomor baru, sedangkan nomor sebelumnya tersimpan di riwayat.</div>${old?`<label>Lokasi Tetap<input class="field" readonly value="${E(branchName(a.branch_id))}"></label>`:`<label>Lokasi / Cabang *<select class="field" name="branch_id" required>${branchOpts(S.profile.branch_id&&role()==='STORE'?S.profile.branch_id:S.data.branches[0]?.id)}</select></label>`}${old?`<label>Jumlah (via SO / Transfer)<input class="field" readonly value="${E(a.qty)}"></label>`:fld('Qty *','qty',1,'number','required min="0" step="1"')}${sel('Kondisi Fisik','condition',conditionOptions,a.condition||'BAGUS')}${sel('Status Pemakaian','status',statusOptions,a.status||'TERPAKAI')}${fld('Posisi / Area','position',a.position)}${fld('Penanggung Jawab','owner_name',a.owner_name)}${fld('No. Registrasi FAT','registration_no',a.registration_no)}${fld('Nomor Seri','serial_no',a.serial_no)}${fld('Tanggal Pembelian','purchase_date',a.purchase_date,'date')}${fld('Harga Pembelian (Rp)','purchase_price',a.purchase_price,'number','min="0" step="0.01"')}${fld('URL Foto Aset (HTTPS)','photo_url',a.photo_url,'url')}${txt('Keterangan','notes',a.notes)}</div>${old?`<div class="divider"></div>${codeHistoryRows(a)}${historyRows(a)}`:''}`,async f=>{
 const fields=['name','brand','category','condition','status','position','owner_name','registration_no','serial_no','notes','photo_url'];const body=Object.fromEntries(fields.map(k=>[k,String(f.get(k)||'').trim()]));
 if(!body.name)throw Error('Nama aset wajib diisi');if(body.photo_url&&!body.photo_url.startsWith('https://'))throw Error('URL foto harus HTTPS');
 body.purchase_date=f.get('purchase_date')||null;body.purchase_price=f.get('purchase_price')===''?null:Number(f.get('purchase_price'));
 if(!old){body.branch_id=f.get('branch_id');body.qty=Number(f.get('qty'));body.created_by=S.user.id;body.source='INPUT MANUAL';}
 if(old)qerr(await S.client.from('ac_assets').update(body).eq('id',id));else qerr(await S.client.from('ac_assets').insert(body));
 },old?'Simpan Perubahan':'Registrasi Aset',!!old);}
function loanForm(){const assets=S.data.assets.filter(x=>x.status==='TERPAKAI'&&x.qty>0&&(globalUser()||x.branch_id===S.profile.branch_id));if(!assets.length)return toast('Belum ada aset yang dapat dipinjam.',true);modal('Catat Peminjaman Aset',`<div class="form-grid"><label class="wide">Pilih Aset<select required class="field" name="asset_id">${options(assets.map(x=>({value:x.id,label:`${x.asset_code} • ${x.name} (${x.qty} unit / ${branchName(x.branch_id)})`})),'')}</select></label>${fld('Peminjam *','borrower','','text','required')}${fld('Qty *','qty','1','number','required min="1"')}${fld('Tanggal Pinjam *','borrow_date',DAY(),'date','required')}${fld('Jatuh Tempo *','due_date',DAY(),'date','required')}${txt('Keterangan','notes')}</div>`,async f=>{
 qerr(await S.client.rpc('ac_create_loan',{p_asset:f.get('asset_id'),p_qty:Number(f.get('qty')),p_borrower:f.get('borrower'),p_start:f.get('borrow_date'),p_due:f.get('due_date'),p_notes:f.get('notes')}));
 },'Simpan Peminjaman');}
function approvalSteps(b){return S.data.approvals.filter(x=>x.ba_id===b.id).sort((x,y)=>x.step_no-y.step_no);}
function printBAHTML(b){const asset=assetObj(b.asset_id)||S.catalog.find(a=>a.id===b.asset_id);const steps=approvalSteps(b);const styles=`<style>body{font-family:Arial,sans-serif;color:#263445;max-width:780px;margin:42px auto;font-size:13px}header{border-bottom:3px solid #f9732b;padding-bottom:15px;display:flex;align-items:center;justify-content:space-between}header strong{font-size:22px}.logo{background:#f9732b;color:#fff;padding:11px;border-radius:9px;font-size:20px;font-weight:900}h1{font-size:22px;text-align:center;margin:30px 0 8px}h2{font-size:14px;margin-top:27px}p{line-height:1.7}table{border-collapse:collapse;width:100%;margin-top:12px}td,th{border:1px solid #cad0d9;padding:11px;text-align:left;vertical-align:top}th{width:32%;background:#f7f8fa}small{color:#68778b}.signs{margin-top:34px}footer{margin-top:40px;border-top:1px solid #ddd;padding-top:8px;color:#888;font-size:10px;text-align:center}@media print{.printbtn{display:none}}</style>`;
 return `<!doctype html><html lang="id"><head><meta charset="utf-8"><title>${E(b.ba_number)}</title>${styles}</head><body><header><div style="display:flex;align-items:center;gap:12px"><span class="logo">38</span><div><strong>TIGALAPAN</strong><div><small>ASSET CONTROL CENTER</small></div></div></div><div style="text-align:right"><b>${E(b.ba_number)}</b><br><small>${DT(b.created_at)}</small></div></header><h1>BERITA ACARA</h1><p style="text-align:center">${E(b.title)}</p><h2>Informasi Berita Acara</h2><table><tr><th>Nomor / Jenis</th><td>${E(b.ba_number)} / ${E(labelStatus(b.ba_type))}</td></tr><tr><th>Aset / Unit</th><td>${E(asset?.name||'Lainnya')} (${F(b.qty)} unit)</td></tr><tr><th>ID Aset saat BA dibuat</th><td>${E(baAssetCodeAtCreation(b)||'—')}</td></tr><tr><th>Asal</th><td>${E(branchName(b.from_branch_id||asset?.branch_id))}</td></tr><tr><th>Tujuan</th><td>${E(branchName(b.to_branch_id))}</td></tr><tr><th>Pembuat</th><td>${E(personName(b.created_by))}</td></tr><tr><th>Penerima</th><td>${E(personName(b.recipient_id))}</td></tr><tr><th>Status</th><td>${E(labelStatus(b.status))}</td></tr></table><h2>Keterangan</h2><p>${E(b.description||'Tidak ada keterangan.')}</p><h2>Jejak Persetujuan Elektronik</h2><table><tr><th style="width:50px">Tahap</th><th>Pihak</th><th>Keputusan</th><th>Waktu / Catatan</th></tr>${steps.map(s=>`<tr><td>${s.step_no}</td><td>${E(s.label)}</td><td>${E(s.decision)}</td><td>${E(personName(s.decided_by))} ${E(DTM(s.decided_at))}<br>${E(s.note)}</td></tr>`).join('')}</table><p><small>Persetujuan dicatat melalui akun login dan jejak audit database. Dokumen ini bukan tanda tangan elektronik tersertifikasi.</small></p><button class="printbtn" onclick="window.print()" style="margin-top:25px;padding:10px;border:0;background:#f9732b;color:#fff;border-radius:7px">Cetak / Simpan PDF</button><footer>Tigalapan Indonesia • Dokumen tercipta secara otomatis dari Asset Control Center</footer></body></html>`;}
function BADetail(id){const b=S.data.ba.find(x=>x.id===id);if(!b)return toast('BA tidak ditemukan.',true);const steps=approvalSteps(b);const transfer=S.data.transfers.find(x=>x.ba_id===b.id);const a=assetObj(b.asset_id)||S.catalog.find(x=>x.id===b.asset_id);modal(`Berita Acara — ${b.ba_number}`,`<div class="actions" style="justify-content:flex-end"><button class="button outline small" type="button" data-action="ba-print" data-id="${E(id)}">${ico('file')} Cetak / View HTML</button></div><h2 class="mt16" style="font-size:19px">${E(b.title)}</h2><p class="muted" style="font-size:12px">${E(b.description)}</p><div class="detail-grid">${hx('Jenis BA',labelStatus(b.ba_type))}${hx('Status',labelStatus(b.status))}${hx('Aset',a?.name)}${hx('ID pada tanggal BA',baAssetCodeAtCreation(b))}${hx('Jumlah',F(b.qty))}${hx('Dari Lokasi',branchName(b.from_branch_id||a?.branch_id))}${hx('Ke Lokasi',branchName(b.to_branch_id))}${hx('Pembuat',personName(b.created_by))}${hx('Penerima',personName(b.recipient_id))}</div><h3 class="section-title">Alur Approval Berjenjang</h3><div class="progress-line">${steps.map(s=>`<div class="step"><div class="step-circle ${s.decision==='DISETUJUI'?'done':s.decision==='DITOLAK'?'stop':''}">${s.decision==='DISETUJUI'?'✓':s.step_no}</div><div><strong>${E(s.label)}</strong> ${tag(s.decision)}<p>${s.decided_at?`${E(personName(s.decided_by))} · ${E(DTM(s.decided_at))}`:'Menunggu giliran tahap ini'}${s.note?' · '+E(s.note):''}</p></div></div>`).join('')}</div>${transfer?`<div class="hint">Transfer: ${E(transfer.id.slice(0,8))} · ${E(labelStatus(transfer.status))} ${transfer.destination_asset_id?'· Aset tujuan: '+E(assetObj(transfer.destination_asset_id)?.asset_code||transfer.destination_asset_id.slice(0,8)):''}</div>`:''}${mayApprove(currentStep(b))&&b.status==='MENUNGGU'?`<div class="actions mt16"><button class="button small" type="button" data-action="ba-approve" data-id="${E(b.id)}">Approve Tahap Berikutnya</button><button class="button danger small" type="button" data-action="ba-reject" data-id="${E(b.id)}">Tolak</button></div>`:''}`,null,'',true);}
function renderBAFields(type){const transferable=type==='TRANSFER',other=type==='LAINNYA';const assets=transferable?S.catalog.filter(x=>x.available>0):(S.data.assets||[]);
 let html=`<label class="wide">${other?'Aset Terkait (opsional)':'Aset *'}<select class="field" name="asset_id" ${other?'':'required'}>${options(assets.map(x=>({value:x.id,label:`${x.asset_code} • ${x.name} • ${branchName(x.branch_id)} (tersedia ${x.available??x.qty})`})),'','-- Pilih Aset --')}</select></label>${fld('Jumlah Unit *','qty',1,'number','required min="1"')}`;
 if(transferable){const branches=S.data.branches.filter(x=>x.active&&(role()!=='STORE'||x.id===S.profile.branch_id));html+=`<label>Lokasi Tujuan *<select class="field" name="to_branch_id" required>${options(branches.map(x=>({value:x.id,label:x.name})),role()==='STORE'?S.profile.branch_id:'','-- Pilih tujuan --')}</select></label><div class="note">Pembuat: user lokasi penerima. Approval: toko asal → GA → FAT.</div>`;}
 else {const users=S.data.profiles.filter(x=>x.active);html+=`<label>User Penerima / Pengesah *<select class="field" name="recipient_id" required>${options(users.map(x=>({value:x.id,label:`${x.display_name} (${x.role} · ${branchName(x.branch_id)})`})), '','-- Pilih penerima --')}</select></label><div class="note">Penerima dipilih sebagai approver tahap pertama.</div>`;}
 return html;
}
function BAForm(initial=''){const allowed=manager()?['ASET_BARU','TRANSFER','LAINNYA']:['TRANSFER'];const type=initial||allowed[0];modal('Buat Berita Acara',`<div class="form-grid">${sel('Jenis BA *','ba_type',allowed,type,'id="ba-type"')}${fld('Judul BA *','title',type==='TRANSFER'?'Berita Acara Transfer Aset':'Berita Acara Serah Terima Aset','text','required')}<div id="ba-extra" class="wide form-grid">${renderBAFields(type)}</div>${txt('Keterangan / Tujuan *','description','','required')}</div><div class="hint mt16">BA dibuat dengan nomor otomatis. Approval dilakukan sesuai jenis BA. Transfer tidak boleh dikirim sebelum semua tahap menyetujui.</div>`,async f=>{
  const type=f.get('ba_type');const input={p_type:type,p_title:f.get('title'),p_description:f.get('description'),p_asset:f.get('asset_id')||null,p_qty:Number(f.get('qty')),p_to_branch:f.get('to_branch_id')||null,p_recipient:f.get('recipient_id')||null,p_other:{source:'WEB APP'}};
  qerr(await S.client.rpc('ac_create_ba',input));
 },'Buat & Ajukan BA');
 $('#ba-type').addEventListener('change',ev=>{$('#ba-extra').innerHTML=renderBAFields(ev.target.value);});}
function decisionBA(id,approve){const b=S.data.ba.find(x=>x.id===id);if(!b)return;modal((approve?'Setujui':'Tolak')+' BA — '+b.ba_number,`<p class="smalltext">Tahap: ${E(currentStep(b)?.label||'—')}. ${approve?'Persetujuan akan membuka tahap berikutnya.':'Penolakan akan menghentikan proses BA dan transfer terkait.'}</p><div class="form-grid">${txt('Catatan Approval','note','','placeholder="Catatan (opsional)"')}</div>`,async f=>{qerr(await S.client.rpc('ac_decide_ba',{p_ba:id,p_approve:approve,p_note:f.get('note')}));},approve?'Setujui':'Tolak BA');}
function SOForm(){const bs=role()==='STORE'?S.data.branches.filter(x=>x.id===S.profile.branch_id):S.data.branches.filter(x=>x.active);modal('Mulai Stock Opname',`<div class="form-grid">${sel('Pilih Cabang *','branch_id',bs.map(x=>({value:x.id,label:x.name})),bs[0]?.id)}${txt('Catatan / Periode','notes')}</div>`,async f=>{const id=qerr(await S.client.rpc('ac_start_so',{p_branch:f.get('branch_id'),p_notes:f.get('notes')}));S.soId=id;},'Mulai SO');}
function maintenanceFields(m={},edit=false){const assets=S.data.assets.filter(a=>a.qty>0);return `<div class="form-grid">${edit?`<div class="wide"><b>${E(assetName(m.asset_id))}</b><p class="smalltext">${E(m.ticket_code)} · ${E(branchName(m.branch_id))}</p></div>`:`<label class="wide">Aset / Inventaris *<select class="field" name="asset_id" required>${options(assets.map(a=>({value:a.id,label:`${a.asset_code} • ${a.name} • ${branchName(a.branch_id)}`})),'','-- Pilih --')}</select></label>`}${sel('Jenis Kebutuhan','maintenance_type',['PERBAIKAN','PREVENTIF','INSPEKSI','PENGGANTIAN','INSTALASI','LAINNYA'],m.maintenance_type||'PERBAIKAN')}${sel('Prioritas','priority',['RENDAH','SEDANG','TINGGI','KRITIS'],m.priority||'SEDANG')}${txt('Keluhan / Kebutuhan *','issue',m.issue,'required')}${txt('Dampak Operasional','impact',m.impact)}${fld('Lokasi Detail / Area','location_detail',m.location_detail)}${fld('PIC Pelaporan / Pekerjaan','pic',m.pic)}${fld('Vendor / Teknisi','vendor',m.vendor)}${fld('Target Selesai','due_date',m.due_date,'date')}${fld('Estimasi Biaya (Rp)','estimated_cost',m.estimated_cost??0,'number','min="0"')}${edit?`${fld('Biaya Aktual (Rp)','actual_cost',m.actual_cost??0,'number','min="0"')}${sel('Status Pengerjaan','status',mm,m.status)}${fld('Tanggal Mulai (lokal)','started_at',m.started_at?m.started_at.slice(0,16):'','datetime-local')}${txt('Tindakan / Pengerjaan','action',m.action)}${txt('Hasil Perbaikan / Evaluasi','result_notes',m.result_notes)}${sel('Kondisi Setelah Pekerjaan','condition_after',['',...conditionOptions],m.condition_after||'')}`:''}${!edit?`<label class="wide">Lampiran Foto (maks. 5 foto, masing-masing 5MB)<input class="field" name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple></label>${sel('Jenis Foto','photo_type',['SEBELUM','PROSES','SESUDAH','LAINNYA'],'SEBELUM')}${fld('Keterangan Foto','caption','')}`:''}</div>`;}
async function uploadMaintenancePhotos(mid,files,kind='SEBELUM',caption=''){
 const list=[...files];let completed=0;
 const report=()=>{let n=$('#upload-progress');if(!n&&$('#modal-root .modalbody')){$('#modal-root .modalbody').insertAdjacentHTML('beforeend','<div id="upload-progress" class="mt16"></div>');n=$('#upload-progress');}if(n)n.innerHTML=progressMeter(completed,list.length,'Unggah Foto');};
 if(list.length)report();if(list.length>5)throw Error('Maksimal 5 foto per unggahan');
 for(const file of list){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Foto harus JPG/PNG/WebP, maksimal 5 MB');
  const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const key=`${mid}/${UID()}.${ext}`;
  qerr(await S.client.storage.from('ac-maintenance').upload(key,file,{upsert:false,contentType:file.type}));
  try{qerr(await S.client.from('ac_maintenance_photos').insert({maintenance_id:mid,storage_key:key,caption,photo_type:kind,uploaded_by:S.user.id}));completed++;report();}catch(err){await S.client.storage.from('ac-maintenance').remove([key]).catch(()=>{});throw err;}
 }
}
function maintenanceNew(){modal('Laporkan Maintenance / Kerusakan',maintenanceFields(),async(f)=>{
 const a=assetObj(f.get('asset_id'));if(!a)throw Error('Aset wajib dipilih');const body={asset_id:a.id,branch_id:a.branch_id,maintenance_type:f.get('maintenance_type'),priority:f.get('priority'),issue:String(f.get('issue')||'').trim(),impact:f.get('impact'),location_detail:f.get('location_detail'),pic:f.get('pic'),vendor:f.get('vendor'),due_date:f.get('due_date')||null,estimated_cost:Number(f.get('estimated_cost')||0),reported_by:S.user.id};
 const m=qerr(await S.client.from('ac_maintenance').insert(body).select().single());try{await uploadMaintenancePhotos(m.id,f.getAll('photos').filter(x=>x instanceof File&&x.size>0),f.get('photo_type'),f.get('caption'));}catch(e){const err=new Error('Tiket '+m.ticket_code+' sudah tersimpan, tetapi unggahan foto gagal: '+e.message+'. Tambahkan foto dari menu Detail tiket.');err.partialSave=true;throw err;}
 },'Kirim Laporan',true);}
function photosHTML(m){const pics=S.data.photos.filter(x=>x.maintenance_id===m.id);return `<div class="photo-grid">${pics.map(p=>`<div class="photo-item"><div data-thumb="${E(p.storage_key)}" style="min-height:75px;background:#f4f6f8;display:grid;place-items:center;border-radius:8px">${ico('file')}</div><span><b>${E(p.photo_type)}</b><br>${E(p.caption||'Bukti foto')}<br>${DT(p.created_at)}</span><button class="ghost-button" type="button" data-action="photo-open" data-key="${E(p.storage_key)}">Lihat Foto ↗</button>${deleteBtn('PHOTO',p.id)}</div>`).join('')||'<p class="smalltext">Belum ada lampiran foto.</p>'}</div>`;}
async function hydrateThumbs(mid){for(const p of S.data.photos.filter(x=>x.maintenance_id===mid)){const el=$$('[data-thumb]').find(x=>x.dataset.thumb===p.storage_key);if(!el)continue;try{const {data,error}=await S.client.storage.from('ac-maintenance').createSignedUrl(p.storage_key,120);if(error)continue;const current=$$('[data-thumb]').find(x=>x.dataset.thumb===p.storage_key);if(current)current.innerHTML=`<img src="${E(data.signedUrl)}" alt="Foto ${E(p.photo_type)}" loading="lazy">`;}catch{}}}
function maintenanceDetail(id){const m=S.data.maintenance.find(x=>x.id===id);if(!m)return;modal(`Maintenance — ${m.ticket_code}`,`<div class="detail-grid">${hx('Aset',assetName(m.asset_id))}${hx('Lokasi',branchName(m.branch_id))}${hx('Kategori',m.maintenance_type)}${hx('Prioritas',m.priority)}${hx('Status',labelStatus(m.status))}${hx('Target',DT(m.due_date))}${hx('Vendor',m.vendor)}${hx('PIC',m.pic)}${hx('Estimasi',RP(m.estimated_cost))}${hx('Biaya Aktual',RP(m.actual_cost))}${hx('Pelapor',personName(m.reported_by))}${hx('Waktu Pelaporan',DTM(m.created_at))}</div><div class="mt16">${progressMeter(({DILAPORKAN:10,DIJADWALKAN:25,DIPROSES:55,MENUNGGU_PART:65,SELESAI:100,DIBATALKAN:0})[m.status]||0,100,'Tahap Maintenance (indikatif)')}</div><div class="section-title">Keluhan / Dampak</div><p class="smalltext">${E(m.issue)}<br>${E(m.impact||'')}</p><div class="section-title">Tindakan & Hasil</div><p class="smalltext">${E(m.action||'Belum dicatat')}<br>${E(m.result_notes||'')}</p><div class="divider"></div><div class="section-title">Lampiran Foto</div>${photosHTML(m)}${activeUser()?`<div class="mt16"><label style="font-size:11px;font-weight:700">Tambah Foto Bukti<input id="upload-photo" class="field" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="actions mt10"><select class="field" id="photo-type" style="max-width:160px">${options(['SEBELUM','PROSES','SESUDAH','LAINNYA'],'PROSES')}</select><input class="field" id="photo-caption" style="max-width:240px" placeholder="Keterangan foto"><button type="button" class="button small" data-action="photo-add" data-id="${E(m.id)}">Upload Foto</button></div></div>`:''}${manager()?`<div class="divider"></div><button type="button" class="button" data-action="maintenance-edit" data-id="${E(m.id)}">Kelola Pekerjaan / Status</button>`:''}`,null,'',true);if(S.client)hydrateThumbs(id);}
function maintenanceEdit(id){const m=S.data.maintenance.find(x=>x.id===id);if(!m)return;modal(`Kelola Maintenance — ${m.ticket_code}`,maintenanceFields(m,true),async f=>{
 const keys=['maintenance_type','priority','issue','impact','location_detail','pic','vendor','action','result_notes','condition_after','status'];const body=Object.fromEntries(keys.map(x=>[x,String(f.get(x)||'')]));
 body.estimated_cost=Number(f.get('estimated_cost')||0);body.actual_cost=Number(f.get('actual_cost')||0);body.due_date=f.get('due_date')||null;body.started_at=f.get('started_at')?new Date(f.get('started_at')).toISOString():null;
 body.closed_at=body.status==='SELESAI'?new Date().toISOString():null;
 if(body.status==='SELESAI'&&(!body.action.trim()||!body.result_notes.trim()))throw Error('Tindakan dan hasil wajib dicatat sebelum menyelesaikan maintenance');
 qerr(await S.client.from('ac_maintenance').update(body).eq('id',id));
 },'Simpan Maintenance',true);}
function userEdit(id){const u=S.data.profiles.find(x=>x.id===id);if(!u)return;modal('Atur Pengguna',`<div class="form-grid">${fld('Nama Pengguna','display_name',u.display_name,'text','required')}${sel('Hak Akses','role',['STORE','GA','FAT','AUDITOR','ADMIN'],u.role)}<label>Lokasi Akun (STORE wajib)<select class="field" name="branch_id">${options(S.data.branches.map(x=>({value:x.id,label:x.name})),u.branch_id,'-- Tidak ada --')}</select></label>${sel('Aktivasi Akun','active',[{value:'true',label:'Aktif'},{value:'false',label:'Nonaktif'}],String(u.active))}</div><p class="smalltext mt16">Pengguna baru login memakai email dan password yang dibuat pada Supabase Authentication. Tidak ada password yang ditampilkan di aplikasi.</p>`,async f=>{
 const body={display_name:f.get('display_name'),role:f.get('role'),branch_id:f.get('branch_id')||null,active:f.get('active')==='true'};
 if(body.active&&body.role==='STORE'&&!body.branch_id)throw Error('STORE harus memiliki lokasi');
 qerr(await S.client.from('ac_profiles').update(body).eq('id',id));
 },'Simpan Akun');}
function branchEdit(id){const b=S.data.branches.find(x=>x.id===id)||{};modal(id?'Edit Cabang':'Tambah Cabang',`<div class="form-grid">${fld('Nama Lokasi / Cabang *','name',b.name,'text','required')}${sel('Status','active',[{value:'true',label:'Aktif'},{value:'false',label:'Nonaktif'}],String(b.active??true))}</div>`,async f=>{
 const body={name:String(f.get('name')).trim().toUpperCase(),active:f.get('active')==='true'};if(!body.name)throw Error('Nama cabang wajib');
 if(id)qerr(await S.client.from('ac_branches').update(body).eq('id',id));else qerr(await S.client.from('ac_branches').insert(body));
 },'Simpan Cabang');}

function csvCell(x){let s=String(x??'');if(/^[\s]*[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function downloadCSV(name,headers,rows){const lines=[headers.map(csvCell).join(','),...rows.map(row=>row.map(csvCell).join(','))];const blob=new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAssets(){const h=['asset_code','name','brand','qty','category','condition','status','branch','position','owner_name','registration_no','serial_no','purchase_date','purchase_price','notes','maintenance_count','source'];const rows=getFilteredAssets().map(a=>[a.asset_code,a.name,a.brand,a.qty,a.category,a.condition,a.status,branchName(a.branch_id),a.position,a.owner_name,a.registration_no,a.serial_no,a.purchase_date,a.purchase_price,a.notes,S.data.maintenance.filter(m=>m.asset_id===a.id).length,a.source]);downloadCSV('tigalapan-master-aset-'+DAY()+'.csv',h,rows);}
function parseCSV(text){const rows=[];let row=[],v='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(quote){if(c==='"'&&text[i+1]==='"'){v+='"';i++;}else if(c==='"')quote=false;else v+=c;}else if(c==='"')quote=true;else if(c===','){row.push(v);v='';}else if(c==='\n'){row.push(v.replace(/\r$/,''));rows.push(row);row=[];v='';}else v+=c;}if(quote)throw Error('CSV berisi tanda kutip yang tidak tertutup');if(row.length||v){row.push(v.replace(/\r$/,''));rows.push(row);}return rows;}
function importForm(){modal('Import Master Aset dari CSV',`<p class="smalltext">Sebelum import, buat seluruh lokasi di Master Lokasi. Kolom <code>branch</code> harus sama persis dengan nama cabang. File hanya boleh format CSV UTF-8, bukan Excel mentah.</p><button class="button outline small" type="button" data-action="csv-template">Unduh Template CSV</button><div class="divider"></div><div class="form-grid"><label class="wide">File CSV<input class="field" name="csv" type="file" accept=".csv,text/csv" required></label></div><div class="hint mt16">Kategori lama yang diawali “ASET” diubah menjadi ASET, selain itu menjadi INVENTARIS. Status lama AKTIF menjadi TERPAKAI dan TIDAK AKTIF menjadi TIDAK TERPAKAI. Periksa hasil klasifikasi di Master Aset setelah import. Import ini menambahkan data, tidak menimpa data yang sudah ada.</div>`,async f=>{
 const file=f.get('csv');if(!(file instanceof File)||!file.size)throw Error('Pilih file CSV');const raw=parseCSV((await file.text()).replace(/^\ufeff/,''));if(raw.length<2)throw Error('CSV kosong');const headers=raw.shift().map(x=>x.trim().toLowerCase());
 const required=['name','qty','branch'];if(required.some(x=>!headers.includes(x)))throw Error('CSV harus memuat kolom name, qty, branch');
 const val=(r,key)=>String(r[headers.indexOf(key)]??'').trim();const data=[];
 for(let i=0;i<raw.length;i++){const r=raw[i];if(!r.some(x=>x.trim()))continue;
  const branch=S.data.branches.find(x=>x.name.toUpperCase()===val(r,'branch').toUpperCase());if(!branch)throw Error(`Baris ${i+2}: cabang '${val(r,'branch')}' tidak terdaftar`);
  const qty=Number(val(r,'qty'));if(!Number.isInteger(qty)||qty<0)throw Error(`Baris ${i+2}: qty tidak valid`);
  const sourceCat=val(r,'category').toUpperCase();const cat=sourceCat.startsWith('ASET')?'ASET':'INVENTARIS';
  const sourceStatus=val(r,'status').toUpperCase();const status=['TIDAK AKTIF','TIDAK TERPAKAI','NONAKTIF','DIPINDAHKAN','PERBAIKAN','PERLU VERIFIKASI'].includes(sourceStatus)?'TIDAK TERPAKAI':'TERPAKAI';
  const condition=conditionOptions.includes(val(r,'condition').toUpperCase())?val(r,'condition').toUpperCase():'BELUM DIPERIKSA';
  data.push({name:val(r,'name'),brand:val(r,'brand'),qty,category:cat,status,condition,branch_id:branch.id,position:val(r,'position'),owner_name:val(r,'owner_name'),registration_no:val(r,'registration_no'),serial_no:val(r,'serial_no'),notes:val(r,'notes'),source:'CSV IMPORT '+DAY(),created_by:S.user.id});
 }
 if(!data.length)throw Error('Tidak ada baris data');if(data.length>3000)throw Error('Batas import 3.000 baris per file');
 if(!confirm(`Import ${data.length} baris sebagai data baru? Pastikan tidak duplikat.`))throw Error('Import dibatalkan');
 for(let i=0;i<data.length;i+=100){const result=await S.client.from('ac_assets').insert(data.slice(i,i+100));if(result.error)throw new Error(`Import sudah memproses ${i} baris; selanjutnya gagal: ${result.error.message}. Periksa duplikasi sebelum mencoba ulang.`);}
 },'Mulai Import');}
async function advanceTransfer(id,action){await run(async()=>{qerr(await S.client.rpc('ac_advance_transfer',{p_transfer:id,p_action:action}));},`Transfer: ${labelStatus(action)} berhasil.`);}
async function saveSO(){const id=S.soId;if(!id)return;const items=$$('tr[data-so-item]').map(tr=>({id:tr.dataset.soItem,qty:tr.querySelector('[name="qty"]')?.value??null,condition:tr.querySelector('[name="condition"]')?.value,notes:tr.querySelector('[name="notes"]')?.value||''}));
 if(!items.length)return;await run(async()=>{qerr(await S.client.rpc('ac_save_so_counts',{p_so:id,p_items:items.map(i=>({id:i.id,qty:i.qty===''?null:Number(i.qty),condition:i.condition,notes:i.notes}))}));},'Hitungan stock opname tersimpan.');}
async function submitSO(){const id=S.soId;if(!id)return;const items=$$('tr[data-so-item]').map(tr=>({id:tr.dataset.soItem,qty:tr.querySelector('[name="qty"]')?.value,condition:tr.querySelector('[name="condition"]')?.value,notes:tr.querySelector('[name="notes"]')?.value||''}));
 if(items.some(x=>x.qty===''))return toast('Qty aktual semua aset harus diisi (boleh 0).',true);
 if(!confirm('Ajukan SO? Setelah diajukan hitungan terkunci hingga GA melakukan approval.'))return;
 await run(async()=>{qerr(await S.client.rpc('ac_save_so_counts',{p_so:id,p_items:items.map(i=>({id:i.id,qty:Number(i.qty),condition:i.condition,notes:i.notes}))}));qerr(await S.client.rpc('ac_submit_so',{p_so:id}));S.soId=null;},'SO diajukan ke GA.');}
function navigateDashboard(el){const dest=el.dataset.dest,filter=el.dataset.filter;S.view=dest;S.page=0;S.soId=null;S.special='';S.quick='ALL';S.filter.status='ALL';S.filter.condition='ALL';
 if(dest==='assets'){if(statusOptions.includes(filter))S.filter.status=filter;else if(filter==='RUSAK'||filter==='NO_FAT')S.special=filter;}
 if(dest!=='assets'&&filter)S.quick=filter;
 render();}
function handleChart(el){const type=el.dataset.filtertype,value=el.dataset.value;S.view='assets';S.page=0;S.soId=null;S.special='';S.filter.status='ALL';S.filter.category='ALL';S.filter.condition='ALL';
 if(type==='branch')S.filter.branch=S.data.branches.find(x=>x.name===value)?.id||'ALL';
 if(type==='category')S.filter.category=value;
 if(type==='status')S.filter.status=value;
 if(type==='condition')S.filter.condition=value;
 render();}
