async function photoAdd(id){const files=$('#upload-photo')?.files;if(!files?.length)return toast('Pilih foto dahulu.',true);
 if(await run(async()=>{await uploadMaintenancePhotos(id,files,$('#photo-type').value,$('#photo-caption').value);},'Foto bukti berhasil ditambahkan.'))closeModal();}
async function cleanupStorageQueue(silent=false){
 if(!isMasterAdmin())return;
 const pending=qerr(await S.client.from('ac_storage_cleanup_queue').select('storage_key').limit(500));
 let removed=0,failed=0;
 for(const entry of pending){
  const key=entry.storage_key;
  const {error}=await S.client.storage.from('ac-maintenance').remove([key]);
  if(error){failed++;console.warn('Storage cleanup pending',key,error);continue;}
  const {error:markError}=await S.client.rpc('ac_admin_storage_mark_removed',{p_storage_key:key});
  if(markError){failed++;console.warn('Could not mark removed file',key,markError);continue;}
  removed++;
 }
 if(!silent)toast(failed?`Database sudah diperbarui, tetapi ${failed} file masih antre untuk dibersihkan.`:`Pembersihan Storage selesai: ${removed} file.`,!!failed);
 return {removed,failed};
}
async function deleteRecord(entity,id){
 if(!isMasterAdmin())return toast('Hanya Master Admin yang boleh menghapus permanen.',true);
 const names={ASSET:'aset',LOAN:'peminjaman',TRANSFER:'transfer',BA:'Berita Acara',SO:'stock opname',MAINTENANCE:'maintenance',PHOTO:'foto',LEGACY:'arsip migrasi',AUDIT:'audit log',USER:'akun pengguna',BRANCH:'cabang'};
 if(!names[entity])throw Error('Jenis data tidak dikenal');
 const preview=qerr(await S.client.rpc('ac_admin_delete_preview',{p_entity:entity,p_id:String(id)}));
 const details=[preview.affected_assets?`${F(preview.affected_assets)} aset terkait`:null,preview.related_records?`${F(preview.related_records)} transaksi/relasi`:null,preview.photos?`${F(preview.photos)} foto Storage`:null].filter(Boolean).join(', ');
 const entered=window.prompt(`HAPUS PERMANEN ${names[entity].toUpperCase()}?\n${details?`Dampak: ${details}\n`:''}${preview.warning?`PERHATIAN: ${preview.warning}\n`:''}Tindakan ini tidak dapat dibatalkan dan akan menghapus data terkait dari database.\nUntuk melanjutkan, ketik HAPUS PERMANEN:`);
 if(entered===null)return;
 if(entered.trim()!=='HAPUS PERMANEN')return toast('Penghapusan dibatalkan karena konfirmasi tidak cocok.',true);
 const ok=await run(async()=>{
  if(entity==='USER'){
   const {data,error}=await S.client.functions.invoke('ac-admin-delete-user',{body:{userId:id,confirmation:'HAPUS PERMANEN'}});
   if(error){let detail='';try{detail=(await error.context?.json())?.error||'';}catch{}throw new Error(detail||error.message);}
   if(!data?.deleted)throw Error(data?.error||'Penghapusan akun belum dikonfirmasi server');
  }else qerr(await S.client.rpc('ac_admin_hard_delete',{p_entity:entity,p_id:String(id),p_confirmation:'HAPUS PERMANEN'}));
  if(entity==='SO')S.soId=null;
 },`${names[entity]} berhasil dihapus permanen dari database.`);
 if(ok){
  closeModal();
  try{const cleanup=await cleanupStorageQueue(true);if(cleanup?.failed)toast(`${cleanup.failed} file foto masih dalam antrean pembersihan Storage.`,true);}catch(err){console.warn('Storage cleanup deferred',err);toast('Data terhapus. Pembersihan Storage tertunda; gunakan tombol Bersihkan Storage di menu Maintenance.',true);}
 }
}
function loginPage(message=''){$('#app').innerHTML=`<div class="auth-page"><div class="auth-card"><div class="brand"><span class="brand-mark">38</span><div>TIGALAPAN<small>ASSET CONTROL CENTER</small></div></div><h1>Selamat Datang</h1><p>Masuk menggunakan akun Supabase perusahaan yang sudah diaktifkan Admin.</p><form id="login-form"><label>Email</label><input class="field" type="email" name="email" required autocomplete="email" placeholder="nama@perusahaan.com"><label>Password</label><input class="field" type="password" name="password" required autocomplete="current-password" placeholder="••••••••••••"><button type="submit" class="button">Masuk ke Dashboard ${ico('arrow')}</button></form>${message?`<div class="alert">${E(message)}</div>`:''}<p style="margin-top:28px;font-size:10px">Pengguna baru dibuat oleh administrator. Jika belum memiliki akun, hubungi GA atau Admin.</p></div></div>`;
 $('#login-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target);loading(true);try{const {error}=await S.client.auth.signInWithPassword({email:String(f.get('email')),password:String(f.get('password'))});if(error)throw error;await authenticated();}catch(e){loginPage('Login gagal: '+(e.message||String(e)));}finally{loading(false);}};
}
function setupPage(){const url=window.ASSET_CONFIG?.supabaseUrl||'';$('#app').innerHTML=`<div class="auth-page"><div class="auth-card" style="width:min(590px,100%)"><div class="brand"><span class="brand-mark">38</span><div>TIGALAPAN<small>ASSET CONTROL CENTER</small></div></div><h1>Aktivasi Koneksi Supabase</h1><p>Antarmuka aplikasi sudah tersedia. Agar fitur berfungsi, isi <code>config.js</code> dengan <b>publishable/anon key</b> proyek Supabase Anda, kemudian jalankan SQL instalasi.</p><div class="hint">Project URL: <b>${E(url)}</b></div><p>Ikuti file <b>README.md</b> dalam paket aplikasi. Pastikan tabel, RLS, akun Admin, dan Storage telah disiapkan sebelum digunakan.</p><p style="color:#b84d40;font-size:11px"><b>Jangan menggunakan service_role atau secret key di frontend.</b></p></div></div>`;}
function inactivePage(){const u=S.profile;$('#app').innerHTML=`<div class="auth-page"><div class="auth-card"><div class="brand"><span class="brand-mark">38</span>TIGALAPAN</div><h1>Akun Belum Diaktifkan</h1><p>Anda sudah login sebagai <b>${E(u.display_name)}</b>, tetapi akun belum mendapat izin mengakses data.</p><div class="hint">Minta Admin menetapkan role, cabang (jika STORE), dan status <b>Aktif</b> pada menu Pengguna.</div><button class="button outline" id="inactive-logout">Keluar</button></div></div>`;$('#inactive-logout').onclick=async()=>{await S.client.auth.signOut();S.profile=null;loginPage();};}
async function authenticated(){const {data:{user},error}=await S.client.auth.getUser();if(error||!user){S.profile=null;loginPage();return;}S.user=user;
 const {data:profile,error:pe}=await S.client.from('ac_profiles').select('*').eq('id',user.id).single();if(pe||!profile){loginPage('Profil akun belum tersedia. Jalankan SQL instalasi atau minta Admin menyiapkan akun.');return;}
 S.profile=profile;if(!profile.active){inactivePage();return;}
 resetFilters();await loadData();render();
}
async function init(){const cfg=window.ASSET_CONFIG||{};if(!cfg.supabaseUrl||!cfg.supabaseAnonKey||cfg.supabaseAnonKey.startsWith('ISI_')){setupPage();return;}
 try{const {createClient}=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');S.client=createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
 const {data:{session}}=await S.client.auth.getSession();if(session)await authenticated();else loginPage();
 S.client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){S.profile=null;S.user=null;loginPage();}});
 }catch(e){console.error(e);setupPage();toast('Tidak dapat menghubungkan Supabase: '+e.message,true);}
}
// Event delegation. Semua perubahan data diverifikasi ulang oleh RLS / SQL RPC di server.
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action],[data-nav]');if(!el)return;
 if(el.dataset.nav){nav(el.dataset.nav);return;}
 const action=el.dataset.action,id=el.dataset.id;
 try{switch(action){
 case 'toggle-sidebar':S.sidebarCollapsed=!S.sidebarCollapsed;localStorage.setItem('ac_sidebar_collapsed',S.sidebarCollapsed?'1':'0');render();break;
 case 'open-nav':$('#sidebar')?.classList.add('open');$('#shade')?.classList.add('open');break;
 case 'close-nav':$('#sidebar')?.classList.remove('open');$('#shade')?.classList.remove('open');break;
 case 'modal-close':closeModal();break;
 case 'delete-record':await deleteRecord(el.dataset.entity,id);break;
 case 'cleanup-storage':await cleanupStorageQueue();break;
 case 'logout':await S.client.auth.signOut();break;
 case 'reset':resetFilters();render();break;
 case 'prev':S.page=Math.max(0,S.page-1);render();break;
 case 'next':S.page++;render();break;
 case 'quick':S.quick=el.dataset.value;S.page=0;render();break;
 case 'dash':navigateDashboard(el);break;
 case 'chart-filter':handleChart(el);break;
 case 'export-assets':exportAssets();break;
 case 'asset-new':assetForm();break;
 case 'asset-edit':assetForm(id);break;
 case 'asset-detail':assetDetail(id);break;
 case 'asset-history':assetDetail(id,true);break;
 case 'asset-import':importForm();break;
 case 'csv-template':downloadCSV('template-master-aset.csv',['name','brand','qty','category','condition','status','branch','position','owner_name','registration_no','serial_no','notes'],[['Meja Kasir','Contoh Merek',1,'ASET','BAGUS','TERPAKAI','CONTOH CABANG','Area Kasir','Penanggung Jawab','','','Contoh data, hapus sebelum import']]);break;
 case 'loan-new':loanForm();break;
 case 'loan-return':if(confirm('Konfirmasi aset telah dikembalikan?'))await run(async()=>qerr(await S.client.rpc('ac_return_loan',{p_id:id,p_note:''})),'Peminjaman dikembalikan.');break;
 case 'ba-new':BAForm();break;
 case 'ba-new-transfer':BAForm('TRANSFER');break;
 case 'ba-detail':BADetail(id);break;
 case 'ba-approve':decisionBA(id,true);break;
 case 'ba-reject':decisionBA(id,false);break;
 case 'ba-print':{const b=S.data.ba.find(x=>x.id===id);if(b){const w=window.open('','_blank');if(!w)throw Error('Izinkan pop-up untuk mencetak BA');w.document.open();w.document.write(printBAHTML(b));w.document.close();}break;}
 case 'tf-ship':if(confirm('Konfirmasi aset sudah diserahkan kepada pengiriman?'))await advanceTransfer(id,'SHIP');break;
 case 'tf-receive':if(confirm('Konfirmasi fisik aset telah diterima di lokasi tujuan? Qty master akan direkonsiliasi.'))await advanceTransfer(id,'RECEIVE');break;
 case 'tf-cancel':if(confirm('Batalkan pengajuan transfer dan BA terkait?'))await advanceTransfer(id,'CANCEL');break;
 case 'so-new':SOForm();break;
 case 'so-open':S.soId=id;render();break;
 case 'so-back':S.soId=null;render();break;
 case 'so-save':await saveSO();break;
 case 'so-submit':await submitSO();break;
 case 'so-approve':if(confirm('Setujui dan terapkan selisih SO pada qty master aset?'))await run(async()=>{qerr(await S.client.rpc('ac_approve_so',{p_so:S.soId}));S.soId=null;},'SO disetujui dan master telah direkonsiliasi.');break;
 case 'maintenance-new':maintenanceNew();break;
 case 'maintenance-detail':maintenanceDetail(id);break;
 case 'maintenance-edit':maintenanceEdit(id);break;
 case 'photo-open':await photoOpen(el.dataset.key);break;
 case 'photo-add':await photoAdd(id);break;
 case 'audit-detail':auditDetail(id);break;
 case 'legacy-detail':legacyDetail(id);break;
 case 'user-edit':userEdit(id);break;
 case 'branch-new':branchEdit();break;
 case 'branch-edit':branchEdit(id);break;
 }}catch(e){errorMessage(e);}
});
document.addEventListener('input',ev=>{if(ev.target.matches('tr[data-so-item] input[name="qty"]')){const entries=$$('tr[data-so-item] input[name="qty"]');const done=entries.filter(x=>x.value!=='').length;const item=$('.so-progress-panel .progress-item');if(item){const total=entries.length,pct=total?Math.round(done/total*100):0;item.setAttribute('aria-valuenow',String(pct));const b=item.querySelector('b');if(b)b.textContent=`${done}/${total} · ${pct}%`;const fill=item.querySelector('.progress-fill');if(fill)fill.style.width=pct+'%';}return;}if(ev.target.id==='f-q'){S.filter.q=ev.target.value;S.page=0;const p=ev.target.selectionStart;$('#content').innerHTML=(S.view==='dashboard'?renderDashboard():S.view==='statuses'?renderStatuses():renderAssets());const q=$('#f-q');q.focus();try{q.setSelectionRange(p,p);}catch{}}});
document.addEventListener('change',ev=>{if(ev.target.id==='legacy-type'){S.legacyType=ev.target.value;render();return;}const f={'f-branch':'branch','f-cat':'category','f-status':'status','f-cond':'condition'};if(f[ev.target.id]){S.filter[f[ev.target.id]]=ev.target.value;S.page=0;S.special='';$('#content').innerHTML=(S.view==='dashboard'?renderDashboard():S.view==='statuses'?renderStatuses():renderAssets());}});
init();
